const CACHE="mono-mock-v65";const ASSETS=["./card-photo.js?v=65","./card-photo.css?v=65","./assets/fonts/card-tech-mono.ttf","./secret-visibility.js?v=65","./launch.js?v=65","./apple-touch-icon.png?v=65","./icon-192.png?v=65","./auth-gate.js?v=65","./auth.css?v=65","./cabinets.js?v=65","./assets/reference/limits-sticker-hq.png","./assets/reference/market-eyes-hq.png","./assets/reference/market-owl-hq.png","./sharp-icons.js?v=65","./bank-detail.js?v=65","./bank-detail.css?v=65","./assets/reference/transfer-pattern.svg","./icon-catalog.js?v=65","./mobile-stability.js?v=65","./mobile-stability.css?v=65","./pull-refresh.js?v=65","./hosted-storage.js?v=65","./card-stable.js?v=65","./card-stable.css?v=65","./profile-pwa.js?v=65","./profile-pwa.css?v=65","./history-glass.js?v=65","./history-glass.css?v=65","./faithful.css?v=65","./faithful-motion.js?v=65","./faithful-entry.js?v=65","./receipt-links.js?v=65","./native-reference.js?v=65","./native-reference.css?v=65","./reference-fidelity.js?v=65","./reference-fidelity.css?v=65","./continuity.js?v=65","./continuity.css?v=65","./motion.js?v=65","./motion.css?v=65","./recording.js?v=65","./recording.css?v=65","./interactions.js?v=65","./interactions.css?v=65","./surfaces.js?v=65","./surfaces.css?v=65","./refinement.css?v=65","./refinement.js?v=65","./reference.css?v=65","./experience.js?v=65","./style.css?v=65","./app.js?v=65","./manifest.json","./icon.svg","./icon.png","./pwa-runtime.js?v=65","./pwa-runtime.css?v=65","./admin-manifest.json"];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('mono-mock-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==self.location.origin||url.pathname.startsWith('/api/'))return;
 if(request.mode==='navigate'){event.respondWith(fetch(new Request(request,{cache:'no-store'})).catch(()=>new Response('<!doctype html><meta name="viewport" content="width=device-width"><style>html{background:#161616;color:white;font:18px system-ui;padding:24px}</style>Потрібне з’єднання з інтернетом. Відкрийте застосунок повторно після підключення.',{headers:{'Content-Type':'text/html; charset=utf-8'}})));return}
 event.respondWith(fetch(request).then(response=>{if(response.ok&&url.pathname.startsWith('/assets/')){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(request,copy)))}return response}).catch(()=>caches.match(request).then(cached=>cached||Response.error())))
});
